// ---- Tabs: edit labels / links here ----
// The link must match the real page URL, otherwise the tab can't be
// detected as active.
const DEFAULT_ITEMS = [
  { label: "Home", link: "/", Icon: HomeIcon },
  { label: "Lens Finder", link: "/sections/lens-test", Icon: LensIcon },
  { label: "Book an Eye Test", link: "/sections/book-an-eye-test", Icon: EyeIcon },
  { label: "Store Locator", link: "/locate-us", Icon: StoreIcon },
  { label: "Virtual Try-On", link: "/collection/eyeglasses", Icon: TryOnIcon },
];

// "/products/", "https://site.com/products?x=1" -> "/products"
const toPath = (link) => {
  if (!link) return "";
  try {
    const path = new URL(link, "https://placeholder.local").pathname.replace(
      /\/+$/,
      ""
    );
    return path || "/";
  } catch (e) {
    return link;
  }
};

// Home only matches "/" exactly; other tabs also match their sub-pages
// (e.g. /locate-us/delhi keeps "Stores" active).
const isActivePath = (current, link) => {
  const target = toPath(link);
  if (!target) return false;
  if (target === "/") return current === "/";
  return current === target || current.startsWith(`${target}/`);
};

export function BottomNavBar({ items = DEFAULT_ITEMS }) {
  // Re-renders on every route change, so the active tab updates automatically
  const { pathname: rawPath } = useLocation();
  const pathname = rawPath.replace(/\/+$/, "") || "/";

  if (!items.length) return null;

  return (
    <>
      {/* Spacer so the end of the footer is never hidden behind the bar */}
      <div className={styles.spacer} aria-hidden="true" />

      <nav className={styles.bottomNav} aria-label="Quick navigation">
        {items.map(({ label, link, Icon }) => {
          const active = isActivePath(pathname, link);
          return (
            <FDKLink
              key={label}
              to={link}
              className={`${styles.navItem} ${
                active ? styles.navItemActive : ""
              }`}
              aria-current={active ? "page" : undefined}
            >
              <span className={styles.navIcon}>
                <Icon />
              </span>
              <span className={styles.navLabel}>{label}</span>
            </FDKLink>
          );
        })}
      </nav>
    </>
  );
}

export default BottomNavBar;